// Social-share image (Open Graph / Twitter / WhatsApp) for the data-driven course pages.
//
// The images are generated by scripts/og/course-og.py into public/images/og/course/ as
// <key>-<lang>.jpg, 1200x630, with everything important inside the centre square so the
// WhatsApp square crop still reads. Keys:
//   <masterclass id> · conversation · conversation-<topic id> · collocations · collocations-<role id>
//
// A missing file fails the build on purpose: a page that points at an image that is not
// there shares as a blank card, and nothing else would report it.

import { existsSync } from "node:fs";
import { join } from "node:path";

export interface OgImage {
  src: string;
  alt: string;
  width: number;
  height: number;
}

export function courseOg(key: string, lang: "en" | "es", alt: string): OgImage {
  const src = `/images/og/course/${key}-${lang}.jpg`;
  if (!existsSync(join(process.cwd(), "public", src))) {
    throw new Error(
      `[courseOg] Missing social image public${src}. Run: python -I scripts/og/course-og.py (with npm run preview running).`,
    );
  }
  return { src, alt, width: 1200, height: 630 };
}
